2	import { wikiPages, sectionBody, BULLET } from './lib.mjs';
3	
4	// Citation discipline: every top-level bullet in a Sources section carries
5	// its real URL — a markdown link or a bare URL both verify; the invariant is
6	// reachability, not link typography. A bullet is judged over its whole
7	// block — the bullet line plus its indented continuation lines — so a
8	// hard-wrapped source whose URL lands on the next line is not a false
9	// positive. Prose paragraphs in the section are allowed and unchecked: a page
10	// honestly explaining its unsourced-hypothesis status in prose passes; a
11	// bullet NAMING a source with no URL is the always-wrong case. No non-empty
12	// requirement (a newborn page is legitimately thin), and no URL liveness
13	// probe (network in a check breaks offline determinism).
14	const URL = /https?:\/\//;
15	
16	const rule = {
17	  id: 'product-wiki-sources',
18	  severity: 'blocking',
19	  doc: 'packs/product-wiki/README.md',
20	  description: 'Every Sources bullet carries its real URL',
21	  why: 'a named source without its URL is an uncited citation — unverifiable by the next pass and by review',
22	
23	  run(ctx) {
24	    const out = [];
25	    for (const page of wikiPages(ctx.files)) {
26	      const text = ctx.read(page);
27	      if (text === null) continue;
28	      const section = sectionBody(text, 'sources');
29	      if (section === null) continue; // page-sections owns the missing heading
30	      for (let i = 0; i < section.length; i++) {
31	        if (!BULLET.test(section[i].text)) continue;
32	        let block = section[i].text;
33	        for (let j = i + 1; j < section.length && /^\s+\S/.test(section[j].text); j++) {
34	          block += ` ${section[j].text.trim()}`;
35	        }
36	        if (!URL.test(block)) {
37	          out.push(finding(rule, {
38	            file: page,
39	            line: section[i].line,
40	            what: `Sources bullet carries no URL: "${section[i].text.trim().slice(0, 80)}"`,
41	            fix: 'every listed source carries its real URL (a markdown link or a bare URL); an honestly-unsourced page explains its status in prose instead of listing URL-less sources',
42	          }));
43	        }
44	      }
45	    }
46	    return out;
47	  },
48	};
49	
50	export default rule;
